import {slides,sections,questions as curatedQuestions,exercises} from './slides.js';
import {sourceQuestions} from './question-bank.js';
import {deepDives,myths} from './deep-dives.js';
import {curriculum,studyCount} from './curriculum.js';
import {walkthroughs} from './walkthroughs.js';
const categoryMap={Foundations:'Beginner',SQL:'Intermediate',Performance:'Performance',Internals:'PostgreSQL Internals',Production:'Architecture','Modern Postgres':'AI'};
const questions=[...sourceQuestions.map(([category,question,answer])=>[categoryMap[category]||category,question,answer]),...curatedQuestions,['Advanced','A long transaction prevents VACUUM from reclaiming versions. What do you inspect?','Find old active transactions and their age, check autovacuum progress and dead tuple estimates, then investigate the application holding the snapshot.'],['Interview','How would you diagnose a slow PostgreSQL query before adding an index?','Capture the exact query and representative data, use EXPLAIN (ANALYZE, BUFFERS), compare estimates and actuals, identify the costly node, change one factor, then rerun.']];
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={i:Math.max(0,Math.min(slides.length-1,Number(new URLSearchParams(location.search).get('slide')||1)-1||0)),step:0,playing:false,playTimer:null,simple:false,deep:false,speaker:false,overview:false,mode:'prepared',theme:localStorage.getItem('pgai.theme')||'dark',amount:1000,tx:'start',accounts:{1:10000,2:5000},txMessage:'',versions:0,dead:0,vacFree:0,vacMessage:'',pool:20,poolStep:0,requests:100,partition:'2026-01',deployCase:0,query:'postgres',vectorQuery:'What is PostgreSQL MVCC?',vectorResult:null,vectorMessage:'',ragStep:0,ragQuestion:'What is PostgreSQL MVCC?',rag:null,bench:null,benchSize:1000000,benchQuery:'email',benchBusy:false,benchProgress:'',plan:null,planSource:'prepared',explainMessage:'',selectedNode:0,study:false,studyIndex:0,rehearsal:false,start:0,sectionStart:0,qa:0,qaCategory:'All',exercise:0,myth:0};
document.documentElement.classList.toggle('light',state.theme==='light');
const flow=(items,active=state.step)=>`<div class="flow">${items.map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="node ${i===active?'active':''}">${esc(x)}</div>`).join('')}</div>`;
const button=(label,action,primary=false)=>`<button class="mini-btn ${primary?'primary':''}" data-action="${action}">${label}</button>`;
const status=(message,kind='')=>`<span class="status ${kind}">${esc(message)}</span>`;
const special={
runtime:()=>`<div class="runtime-grid"><div class="runtime-card"><div class="viz-label">APPLICATION SERVER</div><div class="node ${state.step%3===0?'active':''}">HTTP → API code</div><div class="resource-chips"><span>CPU · handlers</span><span>RAM · app state</span><span>Disk · app files</span></div><small>Validates request, runs business rules, sends SQL.</small></div><div class="runtime-link"><span class="packet">SQL →</span><span>← rows</span></div><div class="runtime-card"><div class="viz-label">POSTGRESQL SERVER</div><div class="node ${state.step%3===1?'active':''}">PostgreSQL process</div><div class="resource-chips"><span>CPU · query work</span><span>RAM · buffers</span><span>Storage · tables + WAL</span></div><small>Manages data, transactions, indexes and recovery.</small></div><div class="viz-caption">Both can share a machine for learning, or run on separate machines. Resources belong to the host running each process.</div></div>`,
create:()=>`<div class="stack" style="width:100%"><div class="viz-label">build one layer at a time</div>${flow(['PostgreSQL server','Database learning','Schema app','Table users','Row (1, Atif)'],state.step%5)}<div class="status">${['Start a PostgreSQL process','CREATE DATABASE learning','CREATE SCHEMA app','CREATE TABLE app.users','INSERT, then SELECT'][state.step%5]}</div></div>`,
relation:()=>`<div class="relation-viz"><div class="math-relation"><div class="eyebrow">RELATION · MATH IDEA</div><div>{ (id, name) → (1, Asha), (2, Atif) }</div><small>Tuple = one row · attribute = one column</small></div><div class="relation-tables"><div class="rel-table"><b>agencies</b><span>id = 7</span><span>name = North</span></div><div class="fk-arrow ${state.step%3===2?'active':''}">← agency_id = 7</div><div class="rel-table"><b>donors</b><span>id = 42</span><span>agency_id = 7</span></div></div><div class="viz-caption">${['A relation describes rows with named columns.','A foreign key checks that 7 exists in agencies.id.','A JOIN matches values at query time; indexes can make access efficient.'][state.step%3]}</div></div>`,
concurrency:()=>{let k=state.step%8,events=['Initial committed row v1 = ₹10,000','T1 BEGIN: snapshot and transaction start','T1 UPDATE: new v2 is uncommitted; T1 holds row lock','T2 UPDATE same row: waits for T1 lock','Reader SELECT: sees committed v1 without waiting for that row lock','T1 COMMIT: v2 becomes visible; lock releases','T2 rechecks and updates, then commits v3','A new READ COMMITTED statement can see v3'];return `<div class="concurrency-viz"><div class="viz-label">ILLUSTRATIVE ORDER · NO CLAIMED DATABASE TIMING</div><div class="timeline-row"><b>T1 · writer</b><span class="phase ${k>=1&&k<=5?'lit':''}">${k<1?'idle':k<2?'BEGIN':k<5?'UPDATE + row lock':'COMMIT ✓'}</span></div><div class="timeline-row"><b>T2 · writer</b><span class="phase ${k===3||k===4?'waiting':k>=6?'lit':''}">${k<3?'idle':k<5?'WAITING on row lock':k<6?'ready to retry':'UPDATE + COMMIT ✓'}</span></div><div class="timeline-row"><b>Reader</b><span class="phase ${k===4||k>=7?'lit':''}">${k<4?'idle':k<7?'reads committed v1':'new statement sees v3'}</span></div><div class="version-line"><span class="version ${k>=2?'old':''}">v1 · committed</span><span class="version ${k>=2&&k<5?'dead':k>=5?'':'old'}">v2 · ${k>=5?'committed':k>=2?'uncommitted':'pending'}</span><span class="version ${k>=6?'':'old'}">v3 · ${k>=6?'committed':'pending'}</span></div><div class="viz-caption">${events[k]}</div><div class="timing-note">No universal transaction time: lock wait lasts until T1 ends or a timeout occurs. Measure elapsed time and lock waits in your workload; keep transactions short.</div></div>`},
views:()=>`<div class="views-viz"><div class="viz-label">BASE TABLE CHANGES → WHAT DOES EACH OBJECT SHOW?</div><div class="node ${state.step%3===0?'active':''}">orders · ${state.step%3===0?'100':'101'} rows</div><div class="views-cols"><div class="view-card"><b>VIEW</b><span>saved SELECT</span><strong>${state.step%3===0?'100':'101'}</strong><small>Reads current base data on query</small></div><div class="view-card"><b>MATERIALIZED VIEW</b><span>stored result</span><strong>${state.step%3===2?'101':'100'}</strong><small>${state.step%3===1?'STALE until REFRESH':'Last refreshed result'}</small></div></div><div class="viz-caption">${['Both start at 100.','New order arrives: normal view sees 101; materialized result stays at 100.','REFRESH MATERIALIZED VIEW recomputes its stored result.'][state.step%3]}</div></div>`,
extensions:()=>`<div class="stack"><div class="viz-label">OPTIONAL MODULES INSTALLED INTO A DATABASE</div><div class="node active">POSTGRESQL CORE</div><div class="arrow">↓ CREATE EXTENSION</div><div class="row">${[['pg_trgm','substring search'],['PostGIS','geospatial'],['vector','embeddings']].map(([name,detail],i)=>`<div class="node ${i===state.step%3?'active':''}">${name}<br><small>${detail}</small></div>`).join('')}</div><div class="viz-caption">The server must have extension files available; permissions and provider support determine what you can enable.</div></div>`,
deploy:()=>{let scenarios=[['Prototype or bursty app','Neon-style serverless','Autoscaling, branching and idle compute fit variable demand; watch wake latency, connection patterns and working-set memory.'],['Steady critical workload','Managed RDS','Choose instance CPU/RAM and storage I/O, backups and HA; measure p95 latency and capacity.'],['Need host-level control','Self-host PostgreSQL','You own patching, backups, replication, monitoring and recovery drills.']];let [workload,choice,why]=scenarios[state.deployCase];return `<div class="stack" style="width:94%"><div class="viz-label">PICK FOR A WORKLOAD, NOT A LOGO</div><div class="row">${['SELF-HOST','NEON-STYLE','RDS'].map((x,i)=>`<div class="node ${[1,2,0][state.deployCase]===i?'active':''}">${x}</div>`).join('')}</div><div class="metric"><small>${esc(workload)}</small><strong>${esc(choice)}</strong><small>${esc(why)}</small></div><div class="resource-chips"><span>CPU & query time</span><span>RAM working set</span><span>storage I/O</span><span>connections</span><span>availability</span></div><div class="sizing-loop">Measure representative traffic → find the saturated resource → size with headroom → load test again</div></div>`},
hero:()=>`<div class="stack"><div style="font:600 clamp(2rem,5vw,5rem) 'Space Grotesk';letter-spacing:-.08em;color:var(--cyan)">POSTGRES<span style="color:var(--lime)">QL</span></div>${flow(['SQL','Database','Production','AI'],state.step%4)}</div>`,
pillars:()=>{const pairs=[['Related records + JOINs','Short-lived key cache'],['Constraints + transactions','Large file bytes'],['Flexible SQL + JSONB','Warehouse-sized analytics'],['Extensions + search','Specialized search at scale']];let k=state.step%pairs.length;return `<div class="choice-viz"><div class="choice-head"><b>POSTGRESQL</b><span>Open-source database server · SQL · durable application data</span></div><div class="choice-grid"><div class="choice-column"><strong>CHOOSE IT FOR</strong>${pairs.map(([yes],i)=>`<div class="choice-row ${i===k?'active':''}">${esc(yes)}</div>`).join('')}</div><div class="choice-column alternative"><strong>ANOTHER TOOL MAY FIT</strong>${pairs.map(([,other],i)=>`<div class="choice-row ${i===k?'active':''}">${esc(other)}</div>`).join('')}</div></div><p>Ask: what are the access patterns, correctness rules and dominant resource costs? These tools can also work together.</p></div>`},
pipeline:()=>flow(['Client','Parse','Plan','Execute','Buffers','Storage'],state.step%6),
table:()=>`<div class="table-viz"><div class="viz-label">server / learning database / app schema / users table</div><table><thead><tr>${[['id','bigint'],['name','text'],['email','text']].map(([name,type],i)=>`<th class="${state.step%5===1&&i===1?'selected':''}">${name}<small>${type}</small></th>`).join('')}</tr></thead><tbody>${[['1','Atif','atif@example.com'],['2','Mira','mira@example.com'],['3','Sam','sam@example.com']].map((r,i)=>`<tr class="${state.step%5===2&&i===0?'selected':''}">${r.map((value,j)=>`<td class="${state.step%5===3&&i===0&&j===1?'selected':''}">${value}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="table-glossary"><span><b>TABLE</b> same shape</span><span><b>COLUMN</b> typed field</span><span><b>ROW</b> one record</span><span><b>CELL</b> one value</span></div><div class="table-caption">${['Table = named collection of similarly shaped rows.','Column = named, typed field such as name text.','Row = one record; tuple is the relational-model word.','Cell = value where a row and column meet.','A PostgreSQL heap tuple is a physical row version on a page.'][state.step%5]}</div></div>`,
relations:()=>`<div class="stack">${['Company','Branch','Agency','Donor'].map((x,i)=>`${i?'<div class="arrow">↓ 1 : many</div>':''}<div class="node ${i===state.step%4?'active':''}">${x}</div>`).join('')}</div>`,
sqlFamilies:()=>{const jobs=[['DDL','DEFINE','CREATE / ALTER / DROP','Shape tables, views and indexes.'],['SELECT','READ','SELECT / JOIN / GROUP BY','Ask for selected rows or summaries.'],['DML','CHANGE','INSERT / UPDATE / DELETE','Add, change or remove rows.'],['TRANSACTION','GROUP','BEGIN / COMMIT / ROLLBACK','Make related changes one unit.'],['ACCESS','AUTHORIZE','GRANT / REVOKE','Choose which roles may act.']];let k=state.step%jobs.length;return `<div class="sql-families"><div class="viz-label">ONE LANGUAGE · FIVE JOBS</div><div class="sql-job-list">${jobs.map(([name,verb],i)=>`<div class="sql-job ${i===k?'active':''}"><b>${name}</b><span>${verb}</span></div>`).join('')}</div><div class="sql-job-detail"><div class="sql-job-meaning">${['Data Definition Language','Querying data','Data Manipulation Language','Transaction control','Access control'][k]}</div><strong>${jobs[k][2]}</strong><p>${jobs[k][3]}</p><small>${k===1?'Try WHERE, ORDER BY, LIMIT, JOIN, GROUP BY, CTE and window functions in Study path.':'See a runnable example and the reason for it in Study path.'}</small></div></div>`},
write:()=>flow(['Client','Parser','Executor','Tuple','WAL','Commit'],state.step%6),
transaction:()=>`<div class="stack"><div class="accounts"><div class="account"><small>Account A</small><strong>₹${Number(state.accounts[1]).toLocaleString('en-IN')}</strong></div><div class="arrow">${state.tx==='committed'?'₹2,000 →':'→'}</div><div class="account"><small>Account B</small><strong>₹${Number(state.accounts[2]).toLocaleString('en-IN')}</strong></div></div><div class="version-line"><div class="version">A old v1</div><div class="version ${state.tx==='pending'?'dead':state.tx==='committed'?'':'old'}">A new v2 · ${state.tx==='pending'?'uncommitted':state.tx==='committed'?'visible':'not created'}</div><div class="version">B old v1</div><div class="version ${state.tx==='pending'?'dead':state.tx==='committed'?'':'old'}">B new v2 · ${state.tx==='pending'?'uncommitted':state.tx==='committed'?'visible':'not created'}</div></div><div class="status">${esc(state.txMessage|| (state.tx==='start'?'Ready to transfer':state.tx==='pending'?'Two UPDATEs are pending in one transaction':state.tx==='committed'?'COMMIT makes both new versions visible':'ROLLBACK keeps original balances visible'))}</div><div class="status">${state.tx==='rolled back'?'Aborted versions are not visible; cleanup occurs later.':'One transaction controls both row updates.'}</div></div>`,
mvcc:()=>`<div class="stack"><div class="row"><div class="node ${state.step===0?'active':''}">T1 starts<br><small>snapshot A</small></div><div class="arrow">→</div><div class="node ${state.step===1?'active':''}">T2 updates<br><small>new version</small></div><div class="arrow">→</div><div class="node ${state.step===2?'active':''}">T1 reads<br><small>old visible row</small></div></div><div class="row"><div class="version old">v1 · balance 100</div><div class="version ${state.step>0?'':'old'}">v2 · balance 120</div></div><div class="viz-caption">Simplified READ COMMITTED snapshot sequence: an already-running statement sees its snapshot; a later statement may see the committed new row.</div></div>`,
growth:()=>`<div class="stack" style="width:85%"><div style="color:var(--cyan);font:600 2rem 'Space Grotesk'">${['10','100','1,000','100,000','1,000,000','10,000,000'][state.step%6]} rows</div><div class="bar" style="width:100%;flex:none;height:22px"><span style="width:${[4,8,17,48,75,100][state.step%6]}%"></span></div><div class="status">One matching email · more candidates to inspect in a full scan</div></div>`,
btree:()=>`<div class="tree"><div class="tree-level"><div class="node ${state.step%3===0?'active':''}">50</div></div><div class="tree-level"><div class="node ${state.step%3===1?'active':''}">25</div><div class="node dim">75</div></div><div class="tree-level"><div class="node dim">10</div><div class="node ${state.step%3===2?'active':''}">42</div><div class="node dim">65</div><div class="node dim">90</div></div><div class="status">Find 42: inspect a path, then fetch the row</div></div>`,
explain:()=>`<div class="explain-viz"><div class="viz-label">${state.planSource==='live'?'LIVE · REAL POSTGRESQL PLAN':'PREPARED · STRUCTURE ONLY'}</div><code>EXPLAIN (ANALYZE, BUFFERS) SELECT … WHERE email = ?</code>${renderPlan(state.plan||{Plan:{'Node Type':'Seq Scan','Relation Name':'demo_users','Plan Rows':1,'Actual Rows':null,'Actual Total Time':null,'Rows Removed by Filter':null,'Shared Hit Blocks':null}})}<div class="status ${state.explainMessage.startsWith('LIVE unavailable')?'error':''}">${esc(state.explainMessage||'Click a node to read estimated rows, actual rows, loops, time and buffers.')}</div></div>`,
lab:()=>`<div class="stack" style="width:100%"><div class="viz-label">Performance lab · ${state.mode==='live'?'LIVE PostgreSQL':'PREPARED teaching mode'}</div>${state.bench?`<div class="metrics">${[['Before',state.bench.before],['After',state.bench.after]].map(([label,b])=>`<div class="metric"><small>${label}</small><strong>${esc(b?.plan?.['Node Type']||'—')}</strong><small>${b?.time==null?'No measured time':b.time.toFixed(3)+' ms'}</small><br><small>Rows removed: ${b?.plan?.['Rows Removed by Filter']??'—'} · Buffer hits: ${b?.plan?.['Shared Hit Blocks']??'—'}</small></div>`).join('')}</div>`:`<div style="font:600 2.2rem 'Space Grotesk';color:var(--cyan)">${state.benchSize.toLocaleString()} rows</div><div class="status">${state.mode==='live'?'Prepare data, run a query, create index, then rerun.':'Illustrative plan only. No measured timing is shown.'}</div>`}</div>`,
pages:()=>`<div class="stack"><div class="viz-label">illustrative 8 KB page</div><div class="cells">${Array.from({length:12},(_,i)=>`<div class="cell ${i<state.step%5?'dead':''}">tuple ${i+1}</div>`).join('')}</div><div class="status">Relation → page → tuple version; shared buffers cache pages</div></div>`,
vacuum:()=>`<div class="stack"><div class="viz-label">illustrative page · ${state.dead} obsolete · ${state.vacFree} reusable</div><div class="cells">${Array.from({length:12},(_,i)=>`<div class="cell ${i<state.dead?'dead':i<state.dead+state.vacFree||i>=8?'free':''}">${i<state.dead?'DEAD':i<state.dead+state.vacFree||i>=8?'FREE':'LIVE'}</div>`).join('')}</div><div class="status">${esc(state.vacMessage||'VACUUM can make eligible dead space reusable')}</div></div>`,
wal:()=>flow(['Change','WAL record','WAL flush','Commit','Data-page flush','Recovery'],state.step%6),
replication:()=>`<div class="stack"><div class="node active">PRIMARY</div><div class="arrow">↓ WAL stream</div><div class="row"><div class="node ${state.step%2?'active':''}">REPLICA A</div><div class="node ${state.step%2?'active':''}">REPLICA B</div></div><div class="status">${state.step%2?'Replicas replay changes; read lag is possible':'Primary accepts writes'}</div></div>`,
pool:()=>`<div class="stack" style="width:90%"><div class="viz-label">illustrative concurrency scheduler</div><div class="row"><div class="metric"><strong>${state.requests}</strong><small>requests</small></div><div class="arrow">→</div><div class="metric"><strong>${state.pool}</strong><small>DB connections</small></div></div><div class="pool-slots">${Array.from({length:Math.min(state.pool,30)},(_,i)=>`<span class="slot ${i<Math.min(state.requests,state.pool)?'busy':''}"></span>`).join('')}</div><div class="metrics"><div class="metric"><strong>${Math.min(state.requests,state.pool)}</strong><small>busy</small></div><div class="metric"><strong>${Math.max(0,state.requests-state.pool)}</strong><small>waiting initially</small></div></div><div class="status live">One request: ${['IDLE','ACQUIRED','BUSY','RELEASED'][state.poolStep%4]}</div></div>`,
partition:()=>`<div class="stack"><div class="viz-label">events by month</div><div class="row">${['2025-12','2026-01','2026-02'].map(x=>`<div class="node ${x===state.partition?'active':'dim'}">${x}</div>`).join('')}</div><div class="status">Predicate selects ${state.partition}; other partitions can be pruned</div></div>`,
scale:()=>`<div class="stack"><div class="row"><div class="stack"><div class="node">ONE DATABASE</div><div class="arrow">↓</div><div class="row"><div class="node">P1</div><div class="node">P2</div><div class="node">P3</div></div><small>partitioning</small></div><div class="stack"><div class="node">ROUTER</div><div class="arrow">↓</div><div class="row"><div class="node">DB1</div><div class="node">DB2</div></div><small>sharding</small></div></div></div>`,
rls:()=>`<div class="stack"><div class="viz-label">tenant A request</div><div class="row"><div class="node">AUTH</div><div class="arrow">→</div><div class="node">ROLE + RLS</div><div class="arrow">→</div><div class="node active">ALLOWED ROWS</div></div><div class="cells">${['A1','B1','A2','B2'].map(x=>`<div class="cell ${x[0]==='B'?'dead':''}">${x}</div>`).join('')}</div><div class="status">B rows are filtered by policy in this teaching example</div></div>`,
supabase:()=>{let pairs=[['Auth','users/identities in auth schema; JWT to roles'],['PostgREST','HTTP API over tables, views and functions; RLS'],['Realtime','database changes via WAL / replication'],['Storage','file objects plus PostgreSQL metadata'],['Edge Functions','application code outside DB, calling APIs or SQL'],['Studio','manage schemas, SQL and database objects']];let [service,role]=pairs[state.step%pairs.length];return `<div class="stack" style="width:100%"><div class="viz-label">SUPABASE SERVICES ↔ POSTGRESQL CAPABILITIES</div><div class="node active" style="font-size:1rem">POSTGRESQL · tables · RLS · views · functions · extensions</div><div class="row" style="flex-wrap:wrap;justify-content:center">${pairs.map(([name],i)=>`<div class="node ${i===state.step%pairs.length?'active':''}" style="min-width:75px">${name}</div>`).join('')}</div><div class="metric"><small>${service} connects to</small><strong style="font-size:1rem">${role}</strong></div><div class="viz-caption">PostgreSQL is the data core; these services add APIs, identity, realtime delivery, files, functions and administration.</div></div>`},
search:()=>`<div class="stack"><div class="row">${['SQL fields','JSONB','Full text','Vectors'].map((x,i)=>`<div class="node ${i===state.step%4?'active':''}">${x}</div>`).join('')}</div><div class="status">${['Exact structured condition','Flexible document fields','Words and language-aware ranking','Semantic similarity'][state.step%4]}</div></div>`,
vector:()=>`<div class="vector-space">${[['PostgreSQL',25,25],['MySQL',38,34],['SQL',28,48],['Database',44,17],['Football',75,72],['Pizza',83,25],['Query',30,37]].map(([label,x,y])=>`<div class="point ${label==='Query'?'query':x<50?'near':'far'}" style="left:${x}%;top:${y}%">${label}</div>`).join('')}</div><div class="viz-caption">Illustrative 2D map; real model vectors are high-dimensional.</div>`,
pgvector:()=>`<div class="stack" style="width:100%">${flow(['Text','Embedding model','vector column',state.step%2?'HNSW / IVFFlat':'Exact search','Top K'],state.step%5)}${state.vectorResult?`<div class="rag-chunks">${state.vectorResult.map((c,i)=>`<div class="chunk"><b>#${i+1} · distance ${c.distance?.toFixed(3)??'—'}</b>${esc(c.content)}</div>`).join('')}</div>`:''}${state.vectorMessage?`<div class="status ${state.vectorMessage.startsWith('LIVE unavailable')?'error':'live'}">${esc(state.vectorMessage)}</div>`:''}</div>`,
rag:()=>`<div class="stack" style="width:100%"><div class="viz-label">${state.mode==='live'?'LIVE retrieval':'PREPARED example'}</div>${flow(['Question','Embed','Retrieve','Inspect chunks','Answer'],Math.min(state.ragStep,4))}${state.rag?.error?`<div class="status error">LIVE unavailable: ${esc(state.rag.error)}</div>`:''}${state.ragStep>=3&&!state.rag?.error?`<div class="rag-chunks">${(state.rag?.chunks||['MVCC stores row versions','Snapshots determine visibility','VACUUM reuses old space']).map((x,i)=>`<div class="chunk"><b>Chunk ${i+1}</b>${esc(typeof x==='string'?x:x.content)}</div>`).join('')}</div>`:''}${state.ragStep>=4&&!state.rag?.error?`<div class="status live">${esc(state.rag?.answer||'Prepared example: PostgreSQL MVCC lets transactions read suitable row versions using snapshots.')}</div>`:''}</div>`,
resources:()=>`<div class="stack" style="width:90%"><div class="viz-label">illustrative workload pressure</div>${[['CPU',70],['RAM',55],['Disk I/O',state.step%3===0?85:40],['Connections',state.step%3===1?95:48],['Locks',state.step%3===2?80:20]].map(([x,n])=>`<div class="row" style="width:100%"><small style="width:85px">${x}</small><div class="bar"><span style="width:${n}%"></span></div><small>${n}%</small></div>`).join('')}</div>`,
final:()=>`<div class="stack"><div class="row"><div class="node ${state.step%6===0?'active':''}">USER</div><div class="arrow">→</div><div class="node ${state.step%6===1?'active':''}">API + POOL</div><div class="arrow">→</div><div class="node ${state.step%6===2?'active':''}">POSTGRESQL</div></div><div class="arrow">↓</div><div class="row"><div class="node">SQL</div><div class="node">MVCC</div><div class="node">INDEX</div><div class="node">WAL</div></div><div class="arrow">↓</div><div class="row"><div class="node ${state.step%6===3?'active':''}">STORAGE</div><div class="node ${state.step%6===4?'active':''}">pgvector</div><div class="node ${state.step%6===5?'active':''}">RAG → LLM</div></div></div>`
};
function renderPlan(data){
 let root=data.Plan||data,nodes=[];
 const walk=(n,d=0)=>{nodes.push({n,d});(n.Plans||[]).forEach(c=>walk(c,d+1))};
 walk(root);
 let index=Math.min(state.selectedNode,nodes.length-1),n=nodes[index]?.n||root;
 const fact=(label,value)=>`<div class="plan-fact"><small>${label}</small><strong>${value??'—'}</strong></div>`;
 return `<div class="plan-layout"><div class="plan-tree">${nodes.map(({n,d},i)=>`<button class="plan-node ${i===index?'selected':''}" data-action="node:${i}" style="margin-left:${d*16}px">${d?'↳ ':''}${esc(n['Node Type'])} ${esc(n['Relation Name']||'')}</button>`).join('')}</div><div class="plan-facts">${fact('Estimated rows',n['Plan Rows'])}${fact('Actual rows / loop',n['Actual Rows'])}${fact('Planner cost (units)',n['Total Cost'])}${fact('Actual time (ms)',n['Actual Total Time']?.toFixed?.(3))}${fact('Loops',n['Actual Loops'])}${fact('Filtered out',n['Rows Removed by Filter'])}${fact('Buffer hits',n['Shared Hit Blocks'])}${fact('Buffer reads',n['Shared Read Blocks'])}</div></div><div class="plan-note">Costs are estimates in planner units. Actual time appears only after running the query. Rows are emitted per loop, not all rows examined.</div>`
}
function controls(v){const step=`${button('◀ Step back','back')}${button('Next step →','step',true)}${button(state.playing?'Ⅱ Pause':'▶ Play story','play')}`;if(['hero','pipeline','write','mvcc','growth','btree','wal','replication','search','final','relations','relation','runtime','create','concurrency','views','extensions','supabase','table','pages','pillars','sqlFamilies','resources'].includes(v))return `<h3>See it happen</h3><div class="controls">${step}</div>`;
if(v==='explain')return `<h3>Read an actual plan</h3><div class="controls">${button('Run LIVE EXPLAIN','explain-live',true)}${button('Prepared structure','explain-prepared')}</div><div class="status">LIVE needs the local demo API and seeded users.</div>`;
if(v==='deploy')return `<h3>Choose a workload</h3><div class="controls"><select id="deployCase"><option value="0" ${state.deployCase===0?'selected':''}>Prototype / bursty</option><option value="1" ${state.deployCase===1?'selected':''}>Steady / critical</option><option value="2" ${state.deployCase===2?'selected':''}>Host-level control</option></select></div>`;
if(v==='transaction')return `<h3>Try the transfer</h3><div class="controls">${button('Preview updates','tx-pending')}${button('COMMIT','tx-commit',true)}${button('ROLLBACK','tx-rollback')}${button('Reset','tx-reset')}</div>`;
if(v==='vacuum')return `<h3>Change the page</h3><div class="controls">${button('UPDATE row','vac-add')}${button('VACUUM','vac-clean',true)}${button('Reset','vac-reset')}</div>`;
if(v==='pool')return `<h3>Change demand</h3><div class="controls"><label>Pool <select id="poolSize">${[10,20,50,100].map(n=>`<option ${n===state.pool?'selected':''}>${n}</option>`).join('')}</select></label><label>Requests <select id="requestCount">${[10,50,100,500,1000].map(n=>`<option ${n===state.requests?'selected':''}>${n}</option>`).join('')}</select></label>${button('Next lifecycle →','pool-step')}</div>`;
if(v==='partition')return `<h3>Query one month</h3><div class="controls"><select id="partition">${['2025-12','2026-01','2026-02'].map(x=>`<option ${x===state.partition?'selected':''}>${x}</option>`).join('')}</select></div>`;
if(v==='lab')return `<h3>${state.mode==='live'?'Real PostgreSQL lab':'Prepared walkthrough'}</h3><div class="controls"><select id="benchSize">${[100000,500000,1000000,5000000,10000000].map(n=>`<option value="${n}" ${n===state.benchSize?'selected':''}>${n.toLocaleString()} rows</option>`).join('')}</select><select id="benchQuery">${[['email','Email filter'],['broad','Broad filter'],['sort','ORDER BY'],['join','JOIN'],['count','Aggregation'],['page','OFFSET page']].map(([v,l])=>`<option value="${v}" ${v===state.benchQuery?'selected':''}>${l}</option>`).join('')}</select>${button(state.mode==='live'?'Seed':'Show example','seed')}${button('Run before','bench-before')}${button('Create index','bench-index')}${button('Run after','bench-after',true)}${button('Drop index','bench-drop-index')}${button('Clean data','bench-clean')}${button('Reset','bench-reset')}</div><div id="benchStatus" class="status">${esc(state.benchProgress|| (state.benchBusy?'Working…':state.mode==='live'?'Local demo API required.':'Prepared mode does not show invented timings.'))}</div>`;
if(v==='rag')return `<h3>Ask a question</h3><div class="controls"><input id="ragQuestion" type="text" value="${esc(state.ragQuestion)}" aria-label="RAG question">${button('Run retrieval','rag-run',true)}${button('Show answer','rag-answer')}${button('Reset','rag-reset')}</div>`;
if(v==='pgvector')return `<h3>Vector retrieval</h3><div class="controls"><input id="vectorQuery" type="text" value="${esc(state.vectorQuery)}" aria-label="Vector search query">${button('Search top 3','vector-run',true)}${button('Reset','vector-reset')}</div>`;
return `<h3>Explore</h3><div class="controls">${step}</div>`}
function render(){const slide=slides[state.i];document.title=`${slide.title} — PostgreSQL in the Age of AI`;$('#sectionName').textContent=slide.section;$('#stage').innerHTML=`<article class="slide" id="activeSlide"><div class="slide-head"><div class="eyebrow">${esc(slide.kicker)}</div><h1>${esc(slide.title)}</h1><p class="lead">${esc(slide.lead)}</p></div><div class="slide-body"><div class="visual">${special[slide.visual]?.()||flow(['PostgreSQL'])}</div><div class="insight"><div class="takeaway">${esc(noticeText[slide.visual]||slide.lead)}</div>${state.simple?`<div class="simple-tip">Simply put: ${esc(simpleText[slide.id]||slide.lead)}</div>`:''}<div class="detail-card"><h3>${state.deep?'UNDER THE HOOD':'THE MECHANISM'}</h3><p>${esc(state.deep?(curriculum[slide.id]?.[0]?.mechanics||slide.deep):(curriculum[slide.id]?.[0]?.model||slide.lead))}</p>${!state.deep&&curriculum[slide.id]?.[0]?.why?`<p><b>Why:</b> ${esc(curriculum[slide.id][0].why)}</p>`:''}<p><b>${state.deep?'Watch for:':'In practice:'}</b> ${esc(state.deep?(curriculum[slide.id]?.[0]?.pitfall||slide.deep):(curriculum[slide.id]?.[0]?.decision||slide.deep))}</p><div class="chapter-outline"><b>THIS CHAPTER · ${curriculum[slide.id]?.length||0} LESSONS</b>${(curriculum[slide.id]||[]).slice(1,5).map((x,i)=>`<button data-action="study-open:${i+1}">${esc(x.title)} ↗</button>`).join('')}${(curriculum[slide.id]?.length||0)>5?`<span>+ ${(curriculum[slide.id]?.length||0)-5} more in Study path</span>`:''}</div></div><div class="interaction">${controls(slide.visual)}</div></div></div><div class="slide-foot">${button('SQL','sql')}${button('Study this · '+(curriculum[slide.id]?.length||0)+' lessons','study-open')}${button('Q&A','qa')}${button('Exercises','exercises')}${slide.id==='recap'?button('Myths','myths'):''}${state.rehearsal?`<span class="rehearsal" id="timer"></span>`:''}<span class="status" style="margin-left:auto">${state.mode==='live'?'LIVE mode':'PREPARED mode'} · ${slide.minutes} min</span></div></article>`;$('#counter').textContent=`${String(state.i+1).padStart(2,'0')} / ${slides.length}`;$('#progressFill').style.width=`${(state.i+1)/slides.length*100}%`;$('#roadmap').innerHTML=sections.map(x=>`<button class="${x===slide.section?'current':''}" data-section="${x}">${x}</button>`).join('');$('#prevBtn').disabled=state.i===0;$('#nextBtn').disabled=state.i===slides.length-1;$('#simpleBtn').setAttribute('aria-pressed',state.simple);$('#deepBtn').setAttribute('aria-pressed',state.deep);$('#modeBtn').textContent=state.mode.toUpperCase();$('#modeBtn').classList.toggle('active',state.mode==='live');renderDrawer();renderSpeaker();}
const noticeText={runtime:'The API and PostgreSQL are separate processes with separate resource needs.',create:'Create a database, then a schema, table and row.',relation:'Relation means table-like mathematical data; an FK is a separate rule.',concurrency:'A conflicting writer waits; a snapshot reader can still read a committed version.',views:'A view runs its query; a materialized view stores a refreshable result.',extensions:'Extensions add optional types, functions and index methods.',deploy:'Choose capacity and hosting from workload measurements.',hero:'The same database can answer ordinary SQL and support retrieval for AI.',pillars:'PostgreSQL is an open-source SQL database server; choose it for related, reliable application data.',pipeline:'The planner chooses an execution strategy; the executor performs the actual work.',sqlFamilies:'SQL defines, reads and changes data; transactions group work; grants control access.',table:'Rows are records. Columns have types and constraints.',relations:'Foreign keys make the relationship explicit and enforceable.',write:'WAL can be durable before changed data pages are flushed.',transaction:'Both balances change together at COMMIT.',mvcc:'A reader uses a snapshot to decide which row version is visible.',growth:'Result size and work done are different.',btree:'An index narrows candidates, but adds write and storage cost.',explain:'Compare estimated versus actual output rows and buffer use.',lab:'LIVE results come from PostgreSQL; prepared mode has no invented timings.',pages:'A page holds tuple versions; shared buffers cache pages.',vacuum:'Eligible obsolete space becomes reusable.',wal:'The log supports crash recovery.',replication:'Lag means a replica can be behind the primary.',pool:'Waiting requests are controlled instead of opening unlimited connections.',partition:'A matching predicate can skip irrelevant partitions.',scale:'Partitions and shards have different operational costs.',rls:'Policy filters rows after identity and role context are established.',supabase:'PostgreSQL remains the central data store.',search:'Choose retrieval based on the question being asked.',vector:'The 2D plot is a teaching analogy.',pgvector:'Exact search and approximate indexes trade speed and recall.',rag:'Always inspect retrieved chunks before accepting an answer.',resources:'These bars are illustrative, not telemetry.',final:'Each layer solves a specific problem.'};
const simpleText={pillars:'PostgreSQL is software that stores your app data and lets you ask questions with SQL. Choose it when related records and reliable changes matter.',table:'A column is a field, a row is one record, and a table holds records with the same fields.',sql:'SQL lets you create tables, read rows and change them.',runtime:'Your API answers HTTP requests. PostgreSQL runs the data engine and has its own CPU, memory and disk.',create:'Start PostgreSQL, make a database, add a table, then insert a row.',relation:'In database language, relation means a table-shaped collection. A foreign key is a rule linking values.',concurrency:'One person changing a row makes a second changer wait. Readers can still see an older committed version.',views:'A view is a saved query. A materialized view is a saved result that needs refresh.',extensions:'An extension is an add-on installed into a PostgreSQL database.',deploy:'Pick the database service and size after checking your workload and reliability needs.',mvcc:'PostgreSQL keeps older versions so different transactions can safely see the data appropriate to them.',vacuum:'A cleaner makes old, unused row space available again.',pool:'A small group of reusable database connections serves many requests.',wal:'The database keeps a durable change log to recover after a crash.',embeddings:'A model turns text into numbers that can be compared.',rag:'Find useful passages first, then give them to the AI model.',explain:'Ask PostgreSQL to show what it actually did.'};
function renderDrawer(){const d=$('#drawer');d.hidden=!state.overview;if(!state.overview)return;d.innerHTML=`<button data-action="close-overview" style="float:right">✕</button><h2>45-minute talk · ${studyCount} study lessons</h2>${slides.map((x,i)=>`<button data-slide="${i}" class="${i===state.i?'current':''}"><small>${String(i+1).padStart(2,'0')} · ${x.minutes}m · ${curriculum[x.id]?.length||0} lessons</small>${esc(x.title)}</button>`).join('')}`}
function renderSpeaker(){const p=$('#speaker');p.hidden=!state.speaker;if(!state.speaker)return;let x=slides[state.i],sectionMinutes=slides.filter(s=>s.section===x.section).reduce((n,s)=>n+s.minutes,0);p.innerHTML=`<button data-action="close-speaker" style="float:right">✕</button><h2>Speaker notes</h2><div class="eyebrow">${esc(x.title)}</div><p><b>Current section:</b> ${esc(x.section)} · ${sectionMinutes} min target<br><b>Next:</b> ${esc(slides[state.i+1]?.title||'Q&A')}</p><p>${esc(x.note)}</p><p><b>Technical detail</b><br>${esc(x.deep)}</p><button class="mini-btn" data-action="rehearsal">${state.rehearsal?'Stop':'Start'} rehearsal timer</button><p id="speakerTimer" class="rehearsal"></p>`}
function stopStory(){if(state.playTimer)clearInterval(state.playTimer);state.playTimer=null;state.playing=false}
function playStory(){if(state.playing){stopStory();render();return}let visual=slides[state.i].visual,frames={concurrency:8,create:5,relation:3,runtime:3,views:3,extensions:3,supabase:6,table:5,wal:6,final:6,pipeline:6,write:6,growth:6,btree:3,mvcc:3}[visual]||4;state.step=0;state.playing=true;render();state.playTimer=setInterval(()=>{if(state.step>=frames-1){stopStory();render();return}state.step++;render()},1250)}
function go(i){closeStudy();stopStory();let oldSection=slides[state.i].section;state.i=Math.max(0,Math.min(slides.length-1,i));if(slides[state.i].section!==oldSection)state.sectionStart=Date.now();state.step=0;state.selectedNode=0;state.ragStep=0;state.overview=false;let url=new URL(location.href);url.searchParams.set('slide',state.i+1);history.replaceState(null,'',url);render()}
const labSQL={email:"SELECT * FROM pgai_demo.demo_users WHERE email = 'user500000@example.test'",broad:'SELECT * FROM pgai_demo.demo_users WHERE bucket < 80',sort:'SELECT id,email FROM pgai_demo.demo_users ORDER BY email LIMIT 20',join:'SELECT u.email,o.amount FROM pgai_demo.demo_orders o JOIN pgai_demo.demo_users u ON u.id=o.user_id WHERE o.amount=7',count:'SELECT bucket,count(*) FROM pgai_demo.demo_users GROUP BY bucket',page:'SELECT id,email FROM pgai_demo.demo_users ORDER BY id OFFSET 500000 LIMIT 20'};
function currentSQL(){return slides[state.i].visual==='lab'?`EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)\n${labSQL[state.benchQuery]};`:slides[state.i].sql}
function showSQL(){let article=$('#activeSlide');article.insertAdjacentHTML('beforeend',`<div class="sql-panel"><button class="mini-btn close" data-action="close-sql">Close ✕</button><div class="eyebrow">${slides[state.i].visual==='lab'?'Exact selected benchmark SQL':'SQL / teaching example'}</div><pre>${esc(currentSQL())}</pre><button class="mini-btn" data-action="copy-sql">Copy SQL</button></div>`)}
function showPanel(type){let isQ=type==='qa',items=isQ?questions.filter(x=>state.qaCategory==='All'||x[0]===state.qaCategory):exercises,index=(isQ?state.qa:state.exercise)%items.length,[cat,q,a]=items[index];$('#activeSlide').insertAdjacentHTML('beforeend',`<div class="sql-panel" id="activityPanel"><button class="mini-btn close" data-action="close-sql">Close ✕</button><div class="eyebrow">${isQ?'Q&A · '+esc(cat)+' · '+items.length+' questions':'Exercise '+(index+1)}</div>${isQ?`<select id="qaCategory" style="background:var(--panel);color:var(--text);padding:.5rem;align-self:flex-start">${['All',...new Set(questions.map(x=>x[0]))].map(c=>`<option ${c===state.qaCategory?'selected':''}>${esc(c)}</option>`).join('')}</select>`:''}<h2 style="font:600 clamp(1.1rem,2vw,2rem) 'Space Grotesk';overflow:auto">${esc(q)}</h2><p class="status">Think before revealing the answer.</p><p id="activityAnswer" hidden style="font-size:1rem;color:var(--lime);overflow:auto">${esc(a)}</p><div class="controls">${button('Reveal answer','reveal',true)}${button('Next','next-'+type)}</div></div>`)}
function showTechnical(){openStudy()}
function openStudy(index=0){state.study=true;state.studyIndex=Math.max(0,Math.min(index,(curriculum[slides[state.i].id]?.length||1)-1));renderStudy()}
function closeStudy(){state.study=false;const panel=$('#studyOverlay');panel.hidden=true;panel.innerHTML=''}
function navigateStudy(direction){const current=curriculum[slides[state.i].id]||[];let next=state.studyIndex+direction;if(next>=0&&next<current.length){openStudy(next);return}let slideIndex=state.i+direction;if(slideIndex<0||slideIndex>=slides.length)return;go(slideIndex);openStudy(direction>0?0:(curriculum[slides[state.i].id]?.length||1)-1)}
function renderStudy(){const panel=$('#studyOverlay');if(!state.study){panel.hidden=true;return}const slide=slides[state.i],items=curriculum[slide.id]||[],item=items[state.studyIndex];panel.hidden=false;panel.innerHTML=`<div class="study-backdrop" data-action="study-close"></div><section class="study-sheet" role="dialog" aria-modal="true" aria-label="Zero to hero study notes"><header class="study-head"><div><div class="eyebrow">ZERO → HERO · ${studyCount} LESSONS IN ${slides.length} SCREENS</div><h2>${esc(slide.title)}</h2></div><button class="mini-btn" data-action="study-close" aria-label="Close study notes">Close ✕</button></header><div class="study-layout"><nav class="study-list" aria-label="Lessons in this screen">${items.map((x,i)=>`<button data-action="study-lesson:${i}" class="${i===state.studyIndex?'active':''}"><small>${String(i+1).padStart(2,'0')}</small>${esc(x.title)}</button>`).join('')}<p>Follow the main deck for the 45-minute talk. Read these lessons for the full course.</p></nav><article class="study-content"><div class="study-progress">LESSON ${state.studyIndex+1} OF ${items.length}</div><h3>${esc(item.title)}</h3><section><h4>What it means</h4><p>${esc(item.model)}</p></section>${item.why?`<section class="study-why"><h4>Why it matters</h4><p>${esc(item.why)}</p></section>`:''}<section><h4>How PostgreSQL does it</h4><p>${esc(item.mechanics)}</p></section>${walkthroughs[item.title]?`<section class="study-walkthrough"><h4>Walk through it</h4><p><b>${esc(walkthroughs[item.title].question)}</b></p><ol>${walkthroughs[item.title].steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p><b>What you should see:</b> ${esc(walkthroughs[item.title].observe)}</p><p><b>Decision:</b> ${esc(walkthroughs[item.title].decision)}</p></section>`:''}<section><h4>Real SQL / command</h4><pre><code>${esc(item.sql)}</code></pre><button class="mini-btn" data-action="study-copy">Copy example</button></section>${slide.id==='sql'?`<section class="study-workshop"><h4>Complete SQL workshop</h4><p>Run the commands in a disposable database: <code>psql -v ON_ERROR_STOP=1 -d learning -f examples/sql-workshop.sql</code>. <a href="./examples/sql-workshop.sql" download>Download the SQL file ↗</a></p></section>`:''}<section><h4>Production decision</h4><p>${esc(item.decision)}</p></section><section class="study-trap"><h4>Common mistake</h4><p>${esc(item.pitfall)}</p></section><p class="study-source"><a href="${esc(item.source)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></p></article></div><footer class="study-foot"><button class="mini-btn" data-action="study-prev" ${state.i===0&&state.studyIndex===0?'disabled':''}>← ${state.studyIndex===0?'Previous screen':'Previous lesson'}</button><span>${state.studyIndex+1} / ${items.length} on this screen</span><button class="mini-btn primary" data-action="study-next" ${state.i===slides.length-1&&state.studyIndex===items.length-1?'disabled':''}>${state.studyIndex===items.length-1?'Next screen':'Next lesson'} →</button></footer></section>`}
function showMyth(){let [claim,answer]=myths[state.myth];$('#activeSlide').insertAdjacentHTML('beforeend',`<div class="sql-panel" id="activityPanel"><button class="mini-btn close" data-action="close-sql">Close ✕</button><div class="eyebrow">POSTGRESQL MYTHS · ${state.myth+1}/${myths.length}</div><h2 style="font:600 clamp(1.3rem,2.5vw,2.5rem) 'Space Grotesk'">“${esc(claim)}”</h2><p class="status">What is incomplete about this claim?</p><p id="activityAnswer" hidden style="font-size:1.1rem;color:var(--lime)">${esc(answer)}</p><div class="controls">${button('Reveal answer','reveal',true)}${button('Next myth','next-myth')}</div></div>`)}
async function api(action,extra={}){let r=await fetch('http://127.0.0.1:8765/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(extra)});let data=await r.json();if(!r.ok)throw Error(data.error||'Local demo unavailable');return data}
async function explainLive(){if(state.mode!=='live'){state.explainMessage='Switch to LIVE to run PostgreSQL EXPLAIN ANALYZE.';render();return}state.explainMessage='Running PostgreSQL EXPLAIN (ANALYZE, BUFFERS)…';render();try{let result=await api('performance',{action:'before',query:'email',size:state.benchSize});state.plan=result.raw;state.planSource='live';state.selectedNode=0;state.explainMessage=`Real execution: ${result.time.toFixed(3)} ms; plan and node fields are from PostgreSQL.`}catch(e){state.explainMessage='LIVE unavailable: '+e.message}render()}
function explainPrepared(){state.plan=null;state.planSource='prepared';state.selectedNode=0;state.explainMessage='Prepared plan structure; no invented actual timing or buffer counts.';render()}
async function benchmark(action){if(state.mode!=='live'){if(state.benchQuery!=='email'){state.bench=null;state.benchProgress='Prepared plan example is available only for the email filter. Use LIVE for this query.';render();return}if(action==='reset'||action==='seed')state.bench=null;else if(action==='before')state.bench={before:{plan:{'Node Type':'Seq Scan'},time:null}};else if(action==='after')state.bench={...(state.bench||{}),after:{plan:{'Node Type':'Index Scan'},time:null}};state.benchProgress='Prepared illustration only; no measured time.';render();return}state.benchBusy=true;state.benchProgress='Working…';render();try{let data=await api('performance',{action,size:state.benchSize,query:state.benchQuery});if(action==='reset')state.bench=null;else if(action==='seed'){state.bench=null;let job={status:'queued'};while(job.status==='queued'||job.status==='working'){await new Promise(r=>setTimeout(r,1000));let response=await fetch(`http://127.0.0.1:8765/api/job/${data.job}`);job=await response.json();state.benchProgress=`Seeding ${Number(job.done||0).toLocaleString()} / ${Number(job.total||state.benchSize).toLocaleString()} rows`;let el=$('#benchStatus');if(el)el.textContent=state.benchProgress}if(job.status==='error')throw Error(job.error);data.message=`${job.message} ${job.seconds?.toFixed(1)} s · ${(job.bytes/1048576).toFixed(1)} MiB`;}else if(action==='before'){state.bench={...(state.bench||{}),before:data};state.plan=data.raw;state.planSource='live';state.selectedNode=0}else if(action==='after'){state.bench={...(state.bench||{}),after:data};state.plan=data.raw;state.planSource='live';state.selectedNode=0}state.benchProgress=data.message||'Done';}catch(e){state.benchProgress=e.message}finally{state.benchBusy=false;render()}}
async function transactionAction(action){if(state.mode==='live'){try{let data=await api('transaction',{action});state.accounts=data.balances;state.txMessage=data.message;state.tx=action==='reset'?'start':action==='commit'?'committed':'rolled back'}catch(e){state.txMessage='LIVE unavailable: '+e.message}}else{state.txMessage='Prepared transaction illustration.';state.tx=action==='reset'?'start':action==='commit'?'committed':'rolled back';state.accounts=action==='commit'?{1:8000,2:7000}:{1:10000,2:5000}}render()}
async function vacuumAction(action){if(state.mode==='live'){try{let data=await api('vacuum',{action});state.vacMessage=data.message;if(action==='update'){state.dead=Math.min(8,state.dead+1);state.vacFree=0}else if(action==='vacuum'){state.vacFree=state.dead;state.dead=0}else{state.dead=0;state.vacFree=0}}catch(e){state.vacMessage='LIVE unavailable: '+e.message}}else{state.vacMessage='Prepared page illustration.';if(action==='update'){state.dead=Math.min(8,state.dead+1);state.vacFree=0}else if(action==='vacuum'){state.vacFree=state.dead;state.dead=0}else{state.dead=0;state.vacFree=0}}render()}
async function vectorRun(){state.vectorQuery=$('#vectorQuery')?.value||state.vectorQuery;if(state.mode==='live'){try{let data=await api('vector',{question:state.vectorQuery});state.vectorResult=data.chunks;state.vectorMessage=data.message}catch(e){state.vectorResult=null;state.vectorMessage='LIVE unavailable: '+e.message}}else{state.vectorResult=null;state.vectorMessage='Prepared mode: retrieval needs pgvector and an embedding service.'}render()}
async function ragRun(){state.ragQuestion=$('#ragQuestion')?.value||state.ragQuestion;if(state.mode==='live'){try{state.rag=await api('rag',{question:state.ragQuestion});state.ragStep=3}catch(e){state.rag={error:e.message};state.ragStep=3}}else{state.rag=state.ragQuestion.trim().toLowerCase()==='what is postgresql mvcc?'?null:{error:'Prepared example only supports “What is PostgreSQL MVCC?” Switch to LIVE for another question.'};state.ragStep=3}render()}
document.addEventListener('click',e=>{let t=e.target.closest('[data-action],[data-slide],[data-section]');if(!t)return;if(t.dataset.slide!=null){go(+t.dataset.slide);return}if(t.dataset.section){go(slides.findIndex(x=>x.section===t.dataset.section));return}let a=t.dataset.action;if(a?.startsWith('study-open:')){openStudy(+a.split(':')[1]);return}if(a?.startsWith('study-lesson:')){openStudy(+a.split(':')[1]);return}if(a?.startsWith('node:')){state.selectedNode=+a.split(':')[1];render();return}switch(a){case'step':stopStory();state.step++;render();break;case'back':stopStory();state.step=Math.max(0,state.step-1);render();break;case'play':playStory();break;case'explain-live':explainLive();break;case'explain-prepared':explainPrepared();break;case'tx-pending':state.tx='pending';state.txMessage='Two UPDATEs pending in one transaction (visual preview).';render();break;case'tx-commit':transactionAction('commit');break;case'tx-rollback':transactionAction('rollback');break;case'tx-reset':transactionAction('reset');break;case'vac-add':vacuumAction('update');break;case'vac-clean':vacuumAction('vacuum');break;case'vac-reset':vacuumAction('reset');break;case'pool-step':state.poolStep++;render();break;case'sql':showSQL();break;case'close-sql':t.closest('.sql-panel')?.remove();break;case'copy-sql':navigator.clipboard?.writeText(currentSQL()).then(()=>{t.textContent='Copied'});break;case'technical':showTechnical();break;case'study-open':openStudy();break;case'study-close':closeStudy();break;case'study-prev':navigateStudy(-1);break;case'study-next':navigateStudy(1);break;case'study-copy':navigator.clipboard?.writeText(curriculum[slides[state.i].id][state.studyIndex].sql).then(()=>{t.textContent='Copied'});break;case'myths':showMyth();break;case'qa':showPanel('qa');break;case'exercises':showPanel('exercises');break;case'reveal':$('#activityAnswer').hidden=false;break;case'next-qa':state.qa=(state.qa+1)%questions.length;$('#activityPanel')?.remove();showPanel('qa');break;case'next-exercises':state.exercise=(state.exercise+1)%exercises.length;$('#activityPanel')?.remove();showPanel('exercises');break;case'next-myth':state.myth=(state.myth+1)%myths.length;$('#activityPanel')?.remove();showMyth();break;case'close-overview':state.overview=false;renderDrawer();break;case'close-speaker':state.speaker=false;renderSpeaker();break;case'rehearsal':state.rehearsal=!state.rehearsal;state.start=Date.now();state.sectionStart=state.start;render();break;case'seed':benchmark('seed');break;case'bench-before':benchmark('before');break;case'bench-index':benchmark('index');break;case'bench-after':benchmark('after');break;case'bench-drop-index':benchmark('drop-index');break;case'bench-clean':benchmark('clean');break;case'bench-reset':benchmark('reset');break;case'vector-run':vectorRun();break;case'vector-reset':state.vectorResult=null;state.vectorMessage='';render();break;case'rag-run':ragRun();break;case'rag-answer':if(!state.rag?.error){state.ragStep=4;render()}break;case'rag-reset':state.ragStep=0;state.rag=null;render();break;}});
document.addEventListener('change',e=>{if(e.target.id==='qaCategory'){state.qaCategory=e.target.value;state.qa=0;$('#activityPanel')?.remove();showPanel('qa');return}if(e.target.id==='deployCase')state.deployCase=+e.target.value;if(e.target.id==='poolSize')state.pool=+e.target.value;if(e.target.id==='requestCount')state.requests=+e.target.value;if(e.target.id==='partition')state.partition=e.target.value;if(e.target.id==='benchSize'){state.benchSize=+e.target.value;state.bench=null;state.benchProgress=''}if(e.target.id==='benchQuery'){state.benchQuery=e.target.value;state.bench=null;state.benchProgress=''}render()});
$('#prevBtn').onclick=()=>go(state.i-1);$('#nextBtn').onclick=()=>go(state.i+1);$('#overviewBtn').onclick=()=>{state.overview=!state.overview;state.speaker=false;renderDrawer();renderSpeaker()};$('#studyBtn').onclick=()=>openStudy();$('#speakerBtn').onclick=()=>{state.speaker=!state.speaker;state.overview=false;renderSpeaker();renderDrawer()};$('#simpleBtn').onclick=()=>{state.simple=!state.simple;render()};$('#deepBtn').onclick=()=>{state.deep=!state.deep;render()};$('#themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('pgai.theme',state.theme);document.documentElement.classList.toggle('light',state.theme==='light')};$('#modeBtn').onclick=()=>{state.mode=state.mode==='prepared'?'live':'prepared';state.bench=null;state.benchProgress='';state.rag=null;state.vectorResult=null;state.vectorMessage='';render()};
function buildPrintDeck(){document.querySelector('#printDeck')?.remove();let deck=document.createElement('div');deck.id='printDeck';deck.innerHTML=slides.map((x,i)=>`<article class="print-page"><div class="eyebrow">${i+1} / ${slides.length} · ${esc(x.section)}</div><h1>${esc(x.title)}</h1><p class="print-lead">${esc(x.lead)}</p><div class="print-visual">${special[x.visual]?.()||''}</div><div class="print-detail"><b>Technical detail</b><p>${esc(x.deep)}</p><pre>${esc(x.sql)}</pre></div></article>`).join('');document.body.append(deck);return deck}
$('#printBtn').onclick=()=>{let deck=buildPrintDeck();window.onafterprint=()=>deck.remove();window.print()};if(new URLSearchParams(location.search).has('print'))buildPrintDeck();
document.addEventListener('keydown',e=>{if(state.study){if(e.key==='Escape'){closeStudy();return}if(e.key==='ArrowRight'){e.preventDefault();navigateStudy(1);return}if(e.key==='ArrowLeft'){e.preventDefault();navigateStudy(-1);return}return}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();go(state.i+1)}else if(e.key==='ArrowLeft'){e.preventDefault();go(state.i-1)}else if(e.key==='Home')go(0);else if(e.key==='End')go(slides.length-1);else if(e.key==='Escape'){state.overview=false;state.speaker=false;renderDrawer();renderSpeaker();document.querySelectorAll('.sql-panel').forEach(x=>x.remove())}else if(e.key.toLowerCase()==='n'){state.speaker=!state.speaker;renderSpeaker()}else if(e.key.toLowerCase()==='o'){state.overview=!state.overview;renderDrawer()}});
setInterval(()=>{if(!state.rehearsal)return;let elapsed=Math.floor((Date.now()-state.start)/1000),remaining=Math.max(0,2700-elapsed),sectionElapsed=Math.floor((Date.now()-state.sectionStart)/1000),sectionBudget=slides.filter(s=>s.section===slides[state.i].section).reduce((n,s)=>n+s.minutes,0)*60,fmt=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;if($('#timer'))$('#timer').textContent=`Rehearsal ${fmt(elapsed)} elapsed · ${fmt(remaining)} remaining`;if($('#speakerTimer'))$('#speakerTimer').textContent=`Total ${fmt(elapsed)} / 45:00 · ${slides[state.i].section} ${fmt(sectionElapsed)} / ${fmt(sectionBudget)}`},1000);
render();
if(new URLSearchParams(location.search).has('study')&&!new URLSearchParams(location.search).has('print'))openStudy(Number(new URLSearchParams(location.search).get('lesson')||0));
